insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('m-collection-s742','milestone','S742''s collection: 25 records','S742 (2026-11-27, the routine''s 12:12Z run): 25 records collected and live (12 passing, 13 named gaps by guarded plans), no outline rows, paid reads about $1.10. Display 5b80d4de75e9 (#3904); the land carries the rest. Parked: Coastline 43057''s staging fix, Orange Coast''s paid read, Cuyamaca 18637 (keep-better after the land).',array['program-requirements','collection','milestone'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('d-applies-on-own-branch-s742','decision','Applies go on their own branch, cut at the worker''s reviewed head','S742 conductor: an apply goes on claude/s742-apply, with the plan''s files taken from the worker''s reviewed head, so a worker''s branch stays free for its own pushes and the conductor''s detached-HEAD apply never moves a worker''s ref. Each apply still takes an APPLY verdict, a clean md5 pre-read and one migrate run at a time.',array['program-requirements','apply','conductor','decision'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('d-coastline-stage-fix-parked-s742','decision','Coastline 43057''s staging fix is parked until a second reader reads it','S742 conductor: Coastline 43057''s paid read 46016403916 ended red at its price step and sent nothing ($0), because a bound pin''s page staged as not found. The fix (f3a01a5b: a bound pin''s page stages as read) is shared reader code with no second reader, so it is parked on claude/s742-readers-stagepin; the land takes claude/s742-readers at 4d394536.',array['program-requirements','coastline','parked','conductor'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('d-orange-coast-read-parked-s742','decision','Orange Coast 08663 and 08626: the paid read is the next session''s','S742 conductor: Orange Coast''s free capture 45999669017 binds both pins (08663 at coverage 0.6, 08626 at 1.0 with held_no_gain). The paid read (only 08663,08626, force 08626, about $0.15) was not dispatched at the wind-down and is the next session''s, from NEXT (3) of the lane.',array['program-requirements','orange-coast','parked','conductor'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('p-compact-live-read-s742','pattern','A live read returns runs grouped with a per-college count and md5','S742: a live read returns live_runs grouped by run with a per-college count and md5, and the conductor expands it (kb/_live_read_expand.py) and verifies it against keep-better''s input. S742''s first full-form reads cost about 35 KB each; the compact form carries the same proof and is the form each reread''s person''s-check look uses.',array['program-requirements','live-read','conductor','pattern'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('p-conductor-carries-ended-worker-s742','pattern','The conductor carries a worker that ended at its limit','S742: keys ended at its run''s limit with San Jose City 38499 unfinished (one cited renumber, JOURN138 for the state''s JournalismJO). The conductor ran a reader, the free reconcile, keep-better and the reread, and the record posted passing at 46011334736. A worker''s unfinished key is the conductor''s, never left as a hold.',array['program-requirements','conductor','san-jose-city','pattern'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('p-paid-read-on-sibling-avoids-cancel-s742','pattern','A paid read goes on a sibling branch, not one with a pending capture','S742: a paid read on a branch with a pending capture run would cancel it (a run in the branch''s concurrency group). Butte 14583''s paid read went on claude/s742-piles-butte so it could not cancel Orange Coast''s capture on claude/s742-piles; Cuyamaca''s and El Camino''s went on claude/s742-readers-cuy and -ec.',array['program-requirements','paid-read','git','pattern'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27'),
('f-cosumnes-pdf-unchanged-s742','fact','Cosumnes River''s hand-filed PDF is unchanged; the capture opens the window a page earlier','S742: the hand-filed Cosumnes River PDF''s sha256 is unchanged. The fresh capture opens the Marketing window one page earlier (p.473, not p.474), which corrects the premise of d-crc-filing-parked-for-moved-pdf-s741 (that the PDF had repaginated). The two S739 tests now read either state, and 33542 passes 19 of 19 on reread 45972311864.',array['program-requirements','cosumnes-river','fact','correction'],'proposed','docs/session_743_handoff.md',null,null,'SkyGodwit (S742)','2026-11-27')
on conflict (slug) do nothing;

insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyGodwit (S742)', 'create', 'S742 (2026-11-27)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('m-collection-s742','d-applies-on-own-branch-s742','d-coastline-stage-fix-parked-s742','d-orange-coast-read-parked-s742','p-compact-live-read-s742','p-conductor-carries-ended-worker-s742','p-paid-read-on-sibling-avoids-cancel-s742','f-cosumnes-pdf-unchanged-s742')
  and m.author = 'SkyGodwit (S742)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');

select slug, kind, status, length(summary) as summary_len from public.cpl_memory
where slug in ('m-collection-s742','d-applies-on-own-branch-s742','d-coastline-stage-fix-parked-s742','d-orange-coast-read-parked-s742','p-compact-live-read-s742','p-conductor-carries-ended-worker-s742','p-paid-read-on-sibling-avoids-cancel-s742','f-cosumnes-pdf-unchanged-s742')
  and author = 'SkyGodwit (S742)'
